import{prepareCompletedUnclaimedJungleReview}from'./exhibit-qa-ready.mjs';
import{prepareJungleMainSession}from'./session-owner.mjs';
import{SpeciesCatalogService}from'../../../species-catalog-service.mjs';
import{canonicalHp}from'../../../canonical-session.mjs';
import{createBattleRules,calculateDamage}from'../../../battle-v3/rules.mjs';
export const GYM5_FIRST_BATTLE_QA_BANNER='Gym5 최초 전투 준비 QA · 정상 생성 Lv100 파티 · 일반 난이도 아님 · 사용자 저장 0';
let preparationUsed=false;
export async function prepareGym5FirstBattleQAStorage({adapter,signal,search}={}){
 if(import.meta.env?.DEV!==true||typeof search!=='string')throw Error('GYM5_FIRST_BATTLE_QA_DEV_ONLY');const q=new URLSearchParams(search);if(q.getAll('jungleNative').length!==1||q.get('jungleNative')!=='1'||q.getAll('jungleQAReady').length!==1||q.get('jungleQAReady')!=='1'||q.getAll('gym5FirstBattleQAReady').length!==1||q.get('gym5FirstBattleQAReady')!=='1'||(q.has('jungleExhibitQAReady')||q.has('prologuePairQAReady')))throw Error('GYM5_FIRST_BATTLE_QA_QUERY_REJECTED');if(preparationUsed)throw Error('GYM5_FIRST_BATTLE_QA_ALREADY_USED');preparationUsed=true;
 const check=()=>{if(signal?.aborted)throw Object.assign(Error('QA_PREPARATION_ABORTED'),{code:'QA_PREPARATION_ABORTED'})};check();const tick=async()=>{await new Promise(r=>setTimeout(r,0));check()};
 const moduleURL=import.meta.url,response=await fetch(new URL('./QA_ORIGINAL_S5_BEFORE_FOOD_NO_GYM5.json',moduleURL),{signal});if(!response.ok)throw Error('GYM5_QA_SOURCE_MISSING');const inputBytes=await response.arrayBuffer(),bytes=inputBytes.slice(0);check();const digest=[...new Uint8Array(await crypto.subtle.digest('SHA-256',bytes))].map(v=>v.toString(16).padStart(2,'0')).join('');if(digest!=='12e14181ddd55fe61b975722e95198a9a9ac1dda733586f35aa44a1ec0ad258a')throw Error('GYM5_QA_SOURCE_PIN');const initial=JSON.parse(new TextDecoder().decode(bytes)),catalog=new SpeciesCatalogService({namespace:'canonical',adapter}),rules=createBattleRules(adapter);if(initial.progress.defeatedTrainers.some(id=>/^GYM_05_SUB_/.test(id)||id==='NPC_GYM_05_MYEONGJU')||initial.progress.completedEvents.includes('RIVAL_03'))throw Error('GYM5_QA_ALREADY_BATTLED');
 const prepared=await prepareCompletedUnclaimedJungleReview({adapter,initialRuntime:initial,signal});check();let owner,battles=0,turns=0;
 const driver=async battle=>{if(++battles!==1)throw Error('QA_ONE_ORIGINAL_BATTLE_ONLY');for(;turns<128;turns++){await tick();const s=battle.snapshot();if(s.phase==='ended')return s;if(s.phase==='forced-switch'){const index=s.party.findIndex(m=>m.hp>0);if(index<0)throw Error('QA_BATTLE_SWITCH_STATE');battle.act({type:'switch',index});continue}const mon=s.party[s.active],enemy=s.opponents[s.enemyActive],moves=mon.moves.filter(m=>m.pp>0),score=id=>{const move=rules.moves[id];return move.power?calculateDamage({rules,catalog,move,attacker:mon,defender:enemy,critical:false,randomPercent:100}).damage:0};moves.sort((a,b)=>score(b.id)-score(a.id));battle.act({type:'move',moveId:moves[0]?.id??'SYSTEM_STRUGGLE'})}throw Error('QA_BATTLE_TURN_BOUND');};
 try{owner=await prepareJungleMainSession({featureGate:'S5_JUNGLE_PAIR_MEMORY_REVIEW_ONLY',storage:prepared.storage,adapter,restore:true,signal});check();const world=owner.bindWorld({hooks:{dialogue:async()=>{check()}},battleDriver:driver,rng:()=>.4});
 const to=async(x,y)=>{check();let f=owner.snapshot().state.foot;if(f[0]!==x&&f[1]!==y)throw Error('QA_NON_AXIS_ROUTE');while(f[0]!==x||f[1]!==y){await tick();const dx=Math.sign(x-f[0])*Math.min(240,Math.abs(x-f[0])),dy=Math.sign(y-f[1])*Math.min(240,Math.abs(y-f[1]));if(owner.move(dx,dy)!==Math.abs(dx||dy))throw Error('QA_NATIVE_WALK_BLOCKED');f=owner.snapshot().state.foot}};
 await to(4084,187);await owner.complete();check();for(const[x,y]of[[4084,494],[480,494],[480,568],[125,568]])await to(x,y);owner.move(-1,0);owner.release();if(!owner.interact().ok)throw Error('QA_INTERIOR_EXIT');owner.release();await to(768,1004);await owner.returnToHub();for(const[x,y]of[[770,1065],[770,630],[3138,630],[3138,536]])await to(x,y);owner.move(100,0);owner.release();const result=await owner.challengeHarin();check();if(result.completed!==true||battles!==1||!world.story.eventCompleted('RIVAL_03'))throw Error('QA_HARIN_WIN_POSTCONDITION');await to(3139,630);await to(380,630);await to(380,530);await owner.getHealBinding().heal('qa-gym5-first-battle:'+world.snapshot().sessionId);check();await to(380,630);await to(3138,630);await to(3138,568);const state=owner.snapshot(),runtime=world.snapshot();if(runtime.progress.defeatedTrainers.some(id=>/^GYM_05_SUB_/.test(id)||id==='NPC_GYM_05_MYEONGJU')||!state.puzzle.cOpen||runtime.progress.items.plant_scan_module!==1||runtime.party.some(m=>m.hp!==canonicalHp(catalog,m.speciesId,m.level)||m.status||m.moves.some(q=>q.pp!==catalog.getMoveById(q.id).pp))||runtime.economy.lastHub!=='CENTER:S5')throw Error('GYM5_FIRST_BATTLE_POSTCONDITION');owner.save();check();return Object.freeze({storage:prepared.storage,report:Object.freeze({banner:GYM5_FIRST_BATTLE_QA_BANNER,sourcePreparation:'Original PROLOGUE-S4 required actions;21 real victories+5 original walked exits; no flags/positions synthesized',initialPartyFixture:'Normal-created six Lv100 after original partner acquisition; fullHP via original heal',battles,turns,originalOutcome:'won',preparedFoot:Object.freeze([3138,568]),facing:state.state.facing,gym5Defeated:Object.freeze([]),originalHarinCompleted:true,originalCenterVisited:true,ordinaryDifficulty:false,userStorageWrites:0,flagsOrPositionInjected:false,battleDriverReturned:false})});
 }finally{owner?.dispose()}
}
